import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if the user is authenticated
    fetch('/api/auth/user/')
      .then(res => res.json())
      .then(data => {
        if (data.authenticated) {
          setUser(data);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching user", err);
        setLoading(false);
      });
  }, []);

  const handleLogin = () => {
    // Redirect to Django MSAL login endpoint
    window.location.href = '/api/auth/login/';
  };

  const handleLogout = () => {
    fetch('/api/auth/logout/', { method: 'POST' })
      .then(() => {
        setUser(null);
        window.location.href = '/';
      });
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <Router>
      <div>
        <nav style={{ padding: '1rem', background: '#f0f0f0', display: 'flex', justifyContent: 'space-between' }}>
          <h2>AP Automation Portal</h2>
          {user ? (
            <div>
              <span style={{ marginRight: '1rem' }}>Welcome, {user.username} ({user.role})</span>
              <button onClick={handleLogout}>Logout</button>
            </div>
          ) : (
            <button onClick={handleLogin}>Login with Microsoft</button>
          )}
        </nav>

        <div style={{ padding: '2rem' }}>
          <Routes>
            <Route path="/" element={
              user ? (
                <div>
                  <h3>Dashboard</h3>
                  <p>You are logged in as a <strong>{user.role}</strong>.</p>
                  {/* Role based rendering */}
                  {user.role === 'STORE_ACCOUNTANT' && <p>You can upload invoices and perform manual corrections here.</p>}
                  {user.role === 'STORE_MANAGER' && <p>You can review and approve items for payment.</p>}
                  {user.role === 'AP_TEAM' && <p>You can oversee reconciliation and handle final processing.</p>}
                </div>
              ) : (
                <div>
                  <h3>Please log in to continue.</h3>
                  <button onClick={handleLogin} style={{ padding: '10px 20px', fontSize: '16px' }}>
                    Login with Microsoft
                  </button>
                </div>
              )
            } />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
